{
 "content": "def transform(grid):
    colors = {v for row in grid for v in row}
    # The background is the most common color; turn it to zero and
    # preserve each non-background cell's color.
    bg = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    return [[0 if v == bg else v for v in row] for row in grid]
