{
 "content": "def transform(grid):
    # Recolor the background to 0 while leaving the sparse marked cells
    # unchanged. The marked color is the least frequent color.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker = min(counts, key=counts.get)
    return [[0 if value == background else marker for value in row] for row in grid]
